<script setup lang="ts">import type{PageConfig}from'~/types/platform';const props=defineProps<{page:PageConfig}>();const{showToast}=useToast();const toggles=ref([true,false,true,true,true,true]);const integrations=['Microsoft 365','WhatsApp','Email','Bank','Tax','Payment Gateway','Cloud Storage','API'];</script><template><PageActions primary-label="Save Settings" :hide-import="true" :hide-filter="true" @create="showToast('Settings saved.')"/><section v-if="page.type==='integrations'" class="integration-grid"><article v-for="(name,i) in integrations" :key="name" class="integration-card"><div class="integration-icon"><AppIcon name="settings"/></div><h3>{{name}}</h3><p>Integration configuration for SOP.</p><div class="integration-status" :class="{off:i>2}"><i></i>{{i<3?'Connected':'Not Connected'}}</div><div class="integration-actions"><button @click="showToast(`${name} configuration opened.`)">{{i<3?'Configure':'Connect'}}</button></div></article></section><section v-else-if="page.type==='backup'" class="platform-card platform-grid-card" style="padding:14px"><h2>Backup & Restore</h2><p>Create an on-demand backup, restore, or download a backup package.</p><div class="backup-actions"><button class="pa-btn primary" @click="showToast('Backup completed successfully.')">Backup Now</button><button class="pa-btn" @click="showToast('Restore validation ready.')">Restore</button><button class="pa-btn" @click="showToast('Backup download prepared.')">Download Backup</button></div></section><section v-else class="platform-card settings-form"><template v-for="(label,i) in ['Email Notification','WhatsApp Notification','In-App Notification','Approval','Due Date','Payment']" :key="label"><div class="toggle-row"><div><b>{{label}}</b><small>Configure {{label.toLowerCase()}} behavior.</small></div><button class="toggle" :class="{on:toggles[i]}" @click="toggles[i]=!toggles[i]"/></div></template></section></template>
